    yaml: "apiVersion: ladder.dev/v1alpha1\nkind: WorkflowBundle\nmetadata:\n  name: manufacturing-line-qualification\n  title: Manufacturing line qualification bundle\n  description: Inspection, nonconformance, CAPA, supplier evidence, and a manufacturing ontology sliver around line qualification.\n  version: 1.0.0\nspec:\n  workflowRef: ladder://workflows/builtin/wf-mfg-02\n  ontology:\n    ref: ladder://ontologies/builtin/manufacturing\n    mode: sliver\n    selection:\n      propertyRefs:\n        - part_material.part_number\n        - part_material.lot_number\n        - quality_inspection.defect_count\n        - quality_inspection.overall_disposition\n        - nonconformance.nonconformance_description\n        - corrective_action.capa_status\n        - supplier.supplier_name\n      relationshipIds: [supplied_by, inspects, identifies, resolved_by]\n  forms:\n    - { ref: ladder://forms/docubricks/manufacturing/quality_inspection_report, role: review }\n    - { ref: ladder://forms/docubricks/manufacturing/nonconformance_report, role: exception }\n    - { ref: ladder://forms/docubricks/manufacturing/corrective_preventive_action, role: completion }\n    - { ref: ladder://forms/docubricks/manufacturing/supplier_scorecard, role: review }\n  documents:\n    - { ref: ladder://documents/docubricks/manufacturing/bill_of_materials, role: supporting }\n    - { ref: ladder://documents/docubricks/manufacturing/certificate_of_analysis, role: supporting }\n  bindings:\n    - id: part-to-product-spec\n      source: { ref: ladder://forms/docubricks/manufacturing/quality_inspection_report, path: /spec/pages/0/sections/3/fields/0 }\n      target: { ref: ladder://workflows/builtin/wf-mfg-02, path: /spec/nodes/0/inputSchema/properties/workflowFields/properties/product_spec }\n      ontologyPropertyRef: part_material.part_number\n      direction: input\n    - id: lot-to-process-flow\n      source: { ref: ladder://forms/docubricks/manufacturing/quality_inspection_report, path: /spec/pages/0/sections/3/fields/1 }\n      target: { ref: ladder://workflows/builtin/wf-mfg-02, path: /spec/nodes/0/inputSchema/properties/workflowFields/properties/process_flow }\n      ontologyPropertyRef: part_material.lot_number\n      direction: input\n    - id: defects-to-capability-gate\n      source: { ref: ladder://forms/docubricks/manufacturing/quality_inspection_report, path: /spec/pages/0/sections/1/fields/4 }\n      target: { ref: ladder://workflows/builtin/wf-mfg-02, path: /spec/nodes/6/config/threshold }\n      ontologyPropertyRef: quality_inspection.defect_count\n      direction: review\n    - id: nonconformance-to-rework\n      source: { ref: ladder://forms/docubricks/manufacturing/nonconformance_report, path: /spec/pages/0/sections/1/fields/1 }\n      target: { ref: ladder://workflows/builtin/wf-mfg-02, path: /spec/nodes/8/prompt }\n      ontologyPropertyRef: nonconformance.nonconformance_description\n      direction: exception\n    - id: capa-status-to-approval\n      source: { ref: ladder://forms/docubricks/manufacturing/corrective_preventive_action, path: /spec/pages/0/sections/4/fields/1 }\n      target: { ref: ladder://workflows/builtin/wf-mfg-02, path: /spec/nodes/9/summary }\n      ontologyPropertyRef: corrective_action.capa_status\n      direction: approval\n    - id: supplier-to-intake\n      source: { ref: ladder://forms/docubricks/manufacturing/supplier_scorecard, path: /spec/pages/0/sections/4/fields/0 }\n      target: { ref: ladder://workflows/builtin/wf-mfg-02, path: /spec/nodes/0/inputSchema/properties/workflowFields/properties/supplier_list }\n      ontologyPropertyRef: supplier.supplier_name\n      direction: input\n",
