    ref: "ladder://documents/builtin/insurance-claim-file",
    kind: "document",
    yaml: "apiVersion: ladder.dev/v1alpha1\nkind: Document\nmetadata:\n  name: insurance-claim-file\n  title: Insurance claim file\n  description: Supporting document contract normalized from DocuBricks; it is not rendered as a form.\n  version: 1.0.0\n  source:\n    system: docubricks\n    sourceId: insurance_insurance_claim_file_v1\n    sourcePath: Schemas/insurance/insurance_claim_file\n    sourceVersion: insurance_insurance_claim_file_v1\nspec:\n  documentType: insurance_claim_file\n  fields:\n    - id: claim-number\n      name: claim_number\n      label: Claim number\n      description: Claim number or file identifier.\n      dataType: string\n      required: true\n      ontologyPropertyRef: insurance_claim.claim_number\n    - id: policy-number\n      name: policy_number\n      label: Policy number\n      dataType: string\n      required: true\n      ontologyPropertyRef: insurance_policy.policy_number\n    - id: insured-name\n      name: insured_name\n      label: Insured name\n      dataType: string\n      ontologyPropertyRef: insured_party.insured_name\n    - id: claimant-name\n      name: claimant_name\n      label: Claimant name\n      dataType: string\n      ontologyPropertyRef: insured_party.claimant_name\n    - id: loss-date\n      name: loss_date\n      label: Loss date\n      dataType: date\n      required: true\n      ontologyPropertyRef: loss_event.loss_date\n    - id: loss-description\n      name: loss_description\n      label: Loss description\n      dataType: string\n      ontologyPropertyRef: loss_event.loss_description\n    - id: claim-status\n      name: claim_status\n      label: Claim status\n      dataType: string\n      ontologyPropertyRef: insurance_claim.claim_status\n    - id: reserve-amount\n      name: reserve_amount\n      label: Reserve amount\n      dataType: number\n      ontologyPropertyRef: insurance_claim.reserve_amount\n    - id: paid-amount\n      name: paid_amount\n      label: Paid amount\n      dataType: number\n      ontologyPropertyRef: insurance_claim.paid_amount\n    - id: coverage-position\n      name: coverage_position\n      label: Coverage position\n      dataType: string\n      ontologyPropertyRef: coverage.coverage_position\n  sections:\n    - id: document-details\n      title: Document details\n      fieldIds: [claim-number, loss-description, claim-status]\n    - id: policy-and-parties\n      title: Policy and parties\n      fieldIds: [policy-number, insured-name, claimant-name]\n    - id: loss-and-financials\n      title: Loss and financials\n      fieldIds: [loss-date, reserve-amount, paid-amount, coverage-position]\n  validationRules:\n    - id: claim-number-present\n      severity: error\n      description: Claim number is required.\n      supported: true\n      rule:\n        op: present\n        field: claim_number\n    - id: reserve-non-negative\n      severity: warning\n      description: Reserve amount should be non-negative when present.\n      supported: true\n      rule:\n        op: gte\n        left: { field: reserve_amount }\n        right: { value: 0 }\n  reviewPolicy:\n    lowConfidenceAction: human-review\n  outputSchema: {}\n  inertSourceMetadata:\n    promptId: prompt_v1.txt\n    modelRoutingId: model_routing.json\n",
